using System;
using Microsoft.Xna.Framework;
using ProjectTower;
using ProjectTower.character;
using ProjectTower.texturesheet;

namespace xCharEdit.Character;

public class Frame
{
	public Part[] part;

	public string name;

	public int parts;

	public const int MAX_PARTS = 32;

	public const int ADJUST_IDX_NONE = -1;

	public const int ADJUST_IDX_TORSO = 0;

	public const int ADJUST_IDX_TORCH = 2;

	public Frame()
	{
		part = new Part[32];
		for (int i = 0; i < part.Length; i++)
		{
			part[i].Init();
		}
		name = "";
	}

	public Frame(Frame keySrc)
	{
		this.part = new Part[32];
		name = keySrc.name;
		for (int i = 0; i < this.part.Length; i++)
		{
			Part part = keySrc.part[i];
			this.part[i] = default;
			Part part2 = this.part[i];
			part2.idx = part.idx;
			part2.location = new Vector2(part.location.X, part.location.Y);
			part2.rotation = part.rotation;
			part2.scaling = new Vector2(part.scaling.X, part.scaling.Y);
			part2.flip = part.flip;
			part2.parent = part.parent;
			part2.parentLocOffset = new Vector2(part.parentLocOffset.X, part.parentLocOffset.Y);
			part2.parentRotationOffset = part.parentRotationOffset;
		}
	}

	public Part GetPart(int idx)
	{
		if (idx < 0)
		{
			return part[0];
		}
		return part[idx];
	}

	public void SetPart(int idx, Part _part)
	{
		part[idx] = _part;
	}

	public Part[] GetPartArray()
	{
		return part;
	}

	public static float LerpRotation(float orig, float next, float progress)
	{
		float num;
		for (num = next - orig; num > (float)Math.PI; num -= (float)Math.PI * 2f)
		{
		}
		for (; num < -(float)Math.PI; num += (float)Math.PI * 2f)
		{
		}
		return orig + num * progress;
	}

	public static Vector2 LerpScale(Vector2 orig, Vector2 next, float progress)
	{
		return orig + (next - orig) * progress;
	}

	public static Vector2 LerpLoc(Vector2 orig, Vector2 next, float progress)
	{
		return orig + (next - orig) * progress;
	}

	public static bool CanLerp(Frame orig, Frame next, int part)
	{
		if (orig.GetPart(part).idx < 0)
		{
			return false;
		}
		if (next.GetPart(part).idx < 0)
		{
			return false;
		}
		if (orig.GetPart(part).idx >= 2000 && next.GetPart(part).idx >= 2000)
		{
			return true;
		}
		if (orig.GetPart(part).idx != next.GetPart(part).idx)
		{
			return false;
		}
		if (orig.GetPart(part).flip != next.GetPart(part).flip)
		{
			return false;
		}
		return true;
	}

	internal bool CheckLoop(int child, int parent)
	{
		if (child == parent)
		{
			return true;
		}
		int num = 0;
		do
		{
			num++;
			if (GetPart(parent).parent == -1)
			{
				return false;
			}
			parent = GetPart(parent).parent;
			if (parent == child)
			{
				return true;
			}
		}
		while (num <= 10000);
		return true;
	}

	internal void SetHierarchy(int parentIdx, int childIdx)
	{
		if (!CheckLoop(childIdx, parentIdx))
		{
			Part part = GetPart(parentIdx);
			Part part2 = GetPart(childIdx);
			part2.parent = parentIdx;
			float angle = Trig.GetAngle(part2.location, part.location);
			angle -= part.rotation;
			float dist = Trig.GetDist(part.location, part2.location);
			part2.parentLocOffset = new Vector2((float)Math.Cos(angle), (float)Math.Sin(angle)) * dist;
			part2.parentRotationOffset = part2.rotation - part.rotation;
			UpdateChildren(parentIdx);
		}
	}

	internal void UpdateChildren(int parentIdx)
	{
		for (int i = 0; i < part.Length; i++)
		{
			if (part[i].idx > -1 && part[i].parent == parentIdx)
			{
				part[i].location = part[parentIdx].location + new Vector2((float)Math.Cos(part[parentIdx].rotation), (float)Math.Sin(part[parentIdx].rotation)) * part[i].parentLocOffset.X + new Vector2((float)Math.Cos(part[parentIdx].rotation + (float)Math.PI / 2f), (float)Math.Sin(part[parentIdx].rotation + (float)Math.PI / 2f)) * part[i].parentLocOffset.Y;
				part[i].rotation = part[parentIdx].rotation + part[i].parentRotationOffset;
				UpdateChildren(i);
			}
		}
	}

	internal void UpdateAllDrawChildren(ProjectTower.character.Character c, int adjustFlags, float adjustVal)
	{
		int num = 0;
		while (true)
		{
			bool flag = false;
			for (int i = 0; i < part.Length; i++)
			{
				if (part[i].idx <= -1)
				{
					continue;
				}
				int num2 = i;
				int num3 = 0;
				while (part[num2].parent > -1)
				{
					num2 = part[num2].parent;
					num3++;
					if (num3 > num)
					{
						break;
					}
				}
				if (num3 == num)
				{
					flag = true;
					if (part[i].parent > -1)
					{
						UpdateSingleDrawChild(c, i, part[i].parent, adjustFlags, adjustVal);
					}
				}
			}
			if (flag)
			{
				num++;
				continue;
			}
			break;
		}
	}

	internal void UpdateSingleDrawChild(ProjectTower.character.Character c, int i, int parentIdx, int adjustFlags, float adjustVal)
	{
		if (part[i].parent != parentIdx)
		{
			return;
		}
		part[i].drawLoc = part[parentIdx].drawLoc + new Vector2((float)Math.Cos(part[parentIdx].drawRotation), (float)Math.Sin(part[parentIdx].drawRotation)) * part[i].drawParentLocOffset.X + new Vector2((float)Math.Cos(part[parentIdx].drawRotation + (float)Math.PI / 2f), (float)Math.Sin(part[parentIdx].drawRotation + (float)Math.PI / 2f)) * part[i].drawParentLocOffset.Y;
		bool flag = true;
		if (c.anim.rope != null && part[i].idx < 1000)
		{
			int flags = Textures.tex[c.draw.texIdx].GetCell(part[i].idx).flags;
			if ((uint)(flags - 28) <= 7u)
			{
				flag = false;
			}
		}
		if (flag)
		{
			part[i].drawRotation = part[parentIdx].drawRotation + part[i].drawParentRotationOffset;
		}
		switch (adjustFlags)
		{
		case 2:
			switch (part[i].idx)
			{
			case 18:
				part[i].drawRotation += adjustVal * 1.5f;
				break;
			case 20:
				part[i].drawRotation = (float)Math.PI / 2f * ((adjustVal < 0f) ? (-1f) : 1f);
				break;
			case 24:
				if (part[i].parent > -1 && part[part[i].parent].idx == 20)
				{
					part[i].drawRotation = 1.3707963f * ((adjustVal < 0f) ? (-1f) : 1f);
				}
				break;
			case 25:
				if (part[i].parent > -1 && part[part[i].parent].idx == 20)
				{
					part[i].drawRotation = -1.7707964f * ((adjustVal < 0f) ? (-1f) : 1f);
				}
				break;
			}
			break;
		case 0:
			if (adjustVal > (float)Math.PI)
			{
				adjustVal -= (float)Math.PI * 2f;
			}
			if (adjustVal < -(float)Math.PI)
			{
				adjustVal += (float)Math.PI * 2f;
			}
			if (part[i].idx < 12)
			{
				part[i].drawRotation += adjustVal * 0.35f;
			}
			if (part[i].idx >= 12 && part[i].idx < 18)
			{
				part[i].drawRotation += adjustVal * 0.5f;
			}
			if (part[i].idx >= 18 && part[i].idx < 20)
			{
				part[i].drawRotation += adjustVal * 0.5f;
			}
			break;
		}
	}

	internal void UpdateDrawChildren(ProjectTower.character.Character c, int parentIdx, int adjustFlags, float adjustVal)
	{
		for (int i = 0; i < part.Length; i++)
		{
			if (part[i].idx <= -1 || part[i].parent != parentIdx)
			{
